WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, context, CAST((status_code & 4) != 0 AS INT) AS flag_bit4, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, context['version'] AS version, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE log_ts >= '2024-03-03') SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, SORT_ARRAY(COLLECT_SET(service)) AS service_list, PERCENTILE_APPROX(status_code, 0.5) AS status_code_p50, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, COUNT(CASE WHEN level = 'WARN' THEN 1 END) AS warn_count, MAX(flag_bit4) AS max_flag_bit4, STDDEV_SAMP(status_code) AS status_code_stddev FROM flattened_attrs GROUP BY hour_window
